import { gradeOn } from '../people/people';
import type { GradeFrom, Hold } from '../people/people';
import { counts, isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { claimDue, rateOn, sumDue } from '../rates/rates';
import type { Late, Rate } from '../rates/rates';

/** A claim's due-by: fixed when it was made, from its grade's terms then. */
export const dueBy = (claim: Claim): string => claim.dueBy;

/** Whether a claim is overdue: open (OPEN or PENDING), and its due-by before the sheet's `today`. */
export const isOverdue = (claim: Claim, today: string): boolean =>
  isOpen(claim) && today !== '' && dueBy(claim) < today;

/**
 * A person's overdue claims that count (not an unbound OPEN one dated within one of their `holds`, as it then counts in
 * no total): how many, and their due figures (with their late charge) added up, skipping n/a.
 */
export function personOverdue(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: string,
  late: Late,
): { count: number; total: string } {
  const overdue = claims.filter((c) => counts(c, holds) && isOverdue(c, today));
  return {
    count: overdue.length,
    total: sumDue(overdue.map((c) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date), floor, late))),
  };
}
}

/**
 * What the late charge and a claim's rounding need: the sheet's late percent (two decimals), its
 * today (yyyy-MM-dd; '' until read) and its policy date (yyyy-MM-dd; '' for its
 * today).
 */
export type Late = { pct: string; today: string; policyDate: string };

/**
 * Whether a claim's live figures round half up: it rounds by a date (its own, or for a correction
 * the date of the claim it corrects) before the sheet's policy date (its today when blank); on or
 * after it they round half to even.
 */
export function roundsHalfUp(claim: Claim, late: Late): boolean {
  const policy = late.policyDate !== '' ? late.policyDate : late.today;
  return (claim.roundDate || claim.date) < policy;
}

/** Whole days from one date (yyyy-MM-dd) to another, worked in UTC so no zone shifts it. */
function daysBetween(from: string, to: string): number {
  const utc = (date: string) => {
    const [y, m, d] = date.split('-').map(Number);
    return Date.UTC(y, m - 1, d);
  };
  return Math.round((utc(to) - utc(from)) / 86_400_000);
}

/**
 * A claim's late charge on its `figure`: for an OPEN or PENDING claim past its due-by (fixed when it was
 * made) on the sheet's today, the late percent of the figure for every full 30 days it is overdue,
 * rounded as the claim rounds; else nothing. A statement never binds it: it follows the sheet's today.
 */
function lateCharge(claim: Claim, figure: string, late: Late): bigint {
  if (!isOpen(claim) || figure === NA || late.today === '' || isCorrection(claim)) return 0n;
  const overdue = daysBetween(claim.dueBy, late.today);
  const periods = overdue > 0 ? Math.floor(overdue / 30) : 0;
  return periods === 0 ? 0n : percentOf(figure, late.pct, BigInt(periods), roundsHalfUp(claim, late));
}

/** Due values added up, skipping n/a. */
export function sumDue(values: string[]): string {
  return showCents(values.filter((v) => v !== NA).reduce((n, v) => n + hundredths(v), 0n));
}

/**
 * A claim's due: the one fixed when it was settled (its late charge frozen in), else the figure its
 * person's last statement bound it to (never while it is PENDING), else its amount at the rate in force on its date, at least
 * the sheet's `floor`; an overdue claim's late charge added on top.
 */
export function claimDue(claim: Claim, pct: string | null, floor: string, late: Late): string {
  if (claim.due !== '') return claim.due;
  const figure = isBound(claim) ? claim.statedDue : due(claim.amount, pct, isCorrection(claim) ? null : floor, roundsHalfUp(claim, late));
  const charge = lateCharge(claim, figure, late);
  return charge === 0n ? figure : showCents(hundredths(figure) + charge);
}

/**
 * A person's due-total: the figures of their claims that count (an unbound OPEN one not when dated within one of their `holds`) (each at the rate in force on its
 * date for their grade in force on its date), added up, skipping n/a. With no rate for their grade
 * today it is n/a, unless a claim that counts keeps a fixed figure (settled, or bound by a
 * statement), has a figure under another grade in force on its date, or has a figure dated on or
 * before today (under a rate that has since ended). Held to the sheet's `cap` ('' for none); n/a is
 * not capped.
 */
export function personDueTotal(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.Settings;

/**
 * A claim's due figure, as the screen shows it: the due fixed when it was settled, else the figure
 * its person's last statement bound it to (never while it is PENDING), else its live due: its amount times its grade's rate in
 * force on its date, divided by 100 and rounded to two decimals, raised to the sheet's floor when
 * below it (a correction, a negative amount, has no floor and no late charge). Null for n/a (no
 * floor applies to n/a). Every rounding of a claim's live figures is by the sheet's policy date
 * ({@link Settings#rounding}): half up when the claim is dated before it, half to even on or after;
 * a correction rounds by the date of the claim it corrects.
 */
public final class ClaimFigure {
    private ClaimFigure() {}

    public static BigDecimal of(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isBound()) return claim.getStatedDue();
        return live(claim, rates, grade, settings, today);
    }

    /** The claim's live due at its grade's rate on its date; a correction has no floor. */
    public static BigDecimal live(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
        RoundingMode mode = rounding(claim, settings, today);
        return Rate.inForce(rates, grade, claim.getDate())
                .map((pct) -> times(claim.getAmount(), pct, mode))
                .map((due) -> claim.isCorrection() ? due : due.max(settings.floor()))
                .orElse(null);
    }

    /** How the claim's live figures round, by the date it rounds by and the sheet's policy date. */
    public static RoundingMode rounding(Claim claim, Settings settings, LocalDate today) {
        return settings.rounding(claim.getRoundDate(), today);
    }

    /**
     * The claim's due with its late charge on top: its figure ({@link #of}) plus the late charge
     * an OPEN or PENDING claim gains while overdue on {@code today}. Null for n/a.
     */
    public static BigDecimal withLate(Claim claim, List<Rate> rates, String grade, Settings settings,
            LocalDate today) {
        BigDecimal figure = of(claim, rates, grade, settings, today);
        return figure == null ? null : figure.add(late(claim, figure, settings, today));
    }

    /**
     * The late charge on a figure: for an OPEN or PENDING claim past its due-by (fixed when it was made)
     * on {@code today}, the sheet's late percent of the figure for every full 30 days it is
     * overdue, rounded to two decimals as the claim rounds; else 0.00. Never bound by a statement:
     * it follows the sheet's today until the claim is settled.
     */
    public static BigDecimal late(Claim claim, BigDecimal figure, Settings settings, LocalDate today) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (!claim.isOpen() || figure == null || claim.isCorrection()) return none;
        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
        long periods = overdue > 0 ? overdue / 30 : 0;
        if (periods == 0) return none;
        return figure.multiply(settings.latePct()).multiply(BigDecimal.valueOf(periods))
                .divide(BigDecimal.valueOf(100), 2, rounding(claim, settings, today));
    }

    /** The amount times the percent, divided by 100 and rounded to two decimals. */
    private static BigDecimal times(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
        return amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
    }
}
